fn is_non_prime(n: u64) -> bool {
    // n is at least 2 per problem statement
    if n == 2 {
        return false;
    }
    
    // Even numbers greater than 2 are composite
    if n % 2 == 0 {
        return true;
    }
    
    // Check odd divisors up to sqrt(n)
    let limit = integer_sqrt(n);
    let mut divisor = 3;
    while divisor <= limit {
        if n % divisor == 0 {
            return true;
        }
        divisor += 2;
    }
    
    false
}

// Helper function to compute integer square root
fn integer_sqrt(n: u64) -> u64 {
    if n <= 1 {
        return n;
    }
    
    let mut low = 0;
    let mut high = n.min(1 << 32); // sqrt(u64::MAX) < 2^32
    while low < high {
        let mid = (low + high + 1) / 2;
        if mid <= n / mid {
            low = mid;
        } else {
            high = mid - 1;
        }
    }
    low
}